<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\DelegateLogin\Infrastructure\Provider;

use Override;
use Throwable;
use GuzzleHttp\Client;
use GuzzleHttp\ClientInterface;
use Civi\Lughauth\Features\Oidc\DelegateLogin\Domain\DelegatedLoginEndpoint;
use Civi\Lughauth\Features\Oidc\DelegateLogin\Domain\DelegatedLoginProvider;
use Civi\Lughauth\Features\Oidc\DelegateLogin\Domain\DelegatedProviderDescription;
use Civi\Lughauth\Features\Oidc\DelegateLogin\Domain\DelegatedUserData;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;

class GitHubOAuthProvider implements DelegatedLoginProvider
{
    private const AUTH_URL = 'https://github.com/login/oauth/authorize';
    private const TOKEN_URL = 'https://github.com/login/oauth/access_token';
    private const API_URL = 'https://api.github.com/user';
    private const EMAIL_URL = 'https://api.github.com/user/emails';

    private readonly string $assetsPath;

    public function __construct(
        AppConfig $config,
        Context $context,
        private readonly string $id,
        private readonly string $clientId,
        private readonly string $clientSecret,
        private readonly ClientInterface $http = new Client()
    ) {
        $this->assetsPath = $config->get('oidc.assets.path', $context->getBaseUrl() . '/oauth/assets/');
    }

    #[Override]
    public function info(): DelegatedProviderDescription
    {
        return new DelegatedProviderDescription(
            id: $this->id,
            name: 'GitHub',
            logo: $this->assetsPath . '/socials/github.png'
        );
    }

    #[Override]
    public function delegeatedUrl(string $redirect, string $state): DelegatedLoginEndpoint
    {
        $url = self::AUTH_URL . '?' . http_build_query([
            'client_id' => $this->clientId,
            'redirect_uri' => $redirect,
            'scope' => 'user:email read:user',
            'state' => $state,
        ]);

        return new DelegatedLoginEndpoint('GET', $url);
    }

    #[Override]
    public function authorize(string $redirect, array $request): ?DelegatedUserData
    {
        try {
            $code = (string) ($request['code'] ?? '');
            if ($code === '') {
                return null;
            }

            $tokenResponse = $this->http->request('POST', self::TOKEN_URL, [
                'headers' => ['Accept' => 'application/json'],
                'json' => [
                    'client_id' => $this->clientId,
                    'client_secret' => $this->clientSecret,
                    'code' => $code,
                    'redirect_uri' => $redirect,
                ],
            ]);

            $tokenData = json_decode((string) $tokenResponse->getBody(), true);
            $accessToken = (string) ($tokenData['access_token'] ?? '');
            if ($accessToken === '') {
                return null;
            }

            $headers = [
                'Authorization' => 'Bearer ' . $accessToken,
                'Accept' => 'application/json',
                'User-Agent' => 'LughAuth',
            ];

            $userResponse = $this->http->request('GET', self::API_URL, ['headers' => $headers]);
            $user = json_decode((string) $userResponse->getBody(), true);

            $email = (string) ($user['email'] ?? '');
            $verified = true;
            if ($email === '') {
                [$email, $verified] = $this->fetchPrimaryEmail($headers);
            }
            if ($email === '') {
                return null;
            }

            return new DelegatedUserData(
                providerUserId: (string) ($user['id'] ?? ''),
                email: $email,
                name: (string) ($user['name'] ?? $user['login'] ?? ''),
                pictureUrl: (string) ($user['avatar_url'] ?? ''),
                emailVerified: $verified
            );
        } catch (Throwable $ex) {
            return null;
        }
    }

    /**
     * @return array{0: string, 1: bool}
     */
    private function fetchPrimaryEmail(array $headers): array
    {
        $response = $this->http->request('GET', self::EMAIL_URL, ['headers' => $headers]);
        $emails = json_decode((string) $response->getBody(), true);
        if (!is_array($emails)) {
            return ['', false];
        }
        foreach ($emails as $item) {
            if (!is_array($item)) {
                continue;
            }
            if (($item['primary'] ?? false) !== true) {
                continue;
            }
            return [(string) ($item['email'] ?? ''), (bool) ($item['verified'] ?? false)];
        }
        return ['', false];
    }
}
